class Solution {public:vector<string>solve(int n,vector<vector<int>>edges){if(!n)return{};const long long inf=LLONG_MAX/4;vector<long long>d(n,inf);d[0]=0;for(int round=0;round<n-1;round++){bool changed=false;for(auto e:edges)if(d[e[0]]!=inf&&d[e[0]]+e[2]<d[e[1]]){d[e[1]]=d[e[0]]+e[2];changed=true;}if(!changed)break;}vector<vector<int>>a(n);vector<bool>bad(n);vector<int>q;for(auto e:edges){a[e[0]].push_back(e[1]);if(d[e[0]]!=inf&&d[e[0]]+e[2]<d[e[1]]&&!bad[e[1]]){bad[e[1]]=true;q.push_back(e[1]);}}for(int i=0;i<(int)q.size();i++)for(int v:a[q[i]])if(!bad[v]){bad[v]=true;q.push_back(v);}vector<string>out(n);for(int i=0;i<n;i++)out[i]=bad[i]?"UNBOUNDED":d[i]==inf?"UNREACHABLE":to_string(d[i]);return out;}};